lv_anim_t * detection_pulse_240_Animation_control_flow(lv_obj_t * target,int delay,int operation,bool ignore,aido_flow_state_t * flow)
{
    const char * id="detection_pulse_240";
    lv_anim_t * active=_ui_anim_group_control(id,target,operation);
    if(operation!=0) return active;
    if(ignore && active) {
        _ui_anim_group_watch(id,target,flow);
        return active;
    }
    return detection_pulse_240_Animation_flow(target,delay,flow);
}
